use glam::DVec3 as V;use ingetrazo_core::{scene::{Scene,SelectionItem},image_plane::ImagePlane,math::Ray};use ingetrazo_tools::{move_tool::MoveTool,base::{Tool,ToolContext}};use std::sync::atomic::{AtomicU64,Ordering};
struct CountAllocator;static ALLOCS:AtomicU64=AtomicU64::new(0);
unsafe impl std::alloc::GlobalAlloc for CountAllocator{unsafe fn alloc(&self,l:std::alloc::Layout)->*mut u8{ALLOCS.fetch_add(1,Ordering::Relaxed);unsafe{std::alloc::System.alloc(l)}}unsafe fn dealloc(&self,p:*mut u8,l:std::alloc::Layout){unsafe{std::alloc::System.dealloc(p,l)}}unsafe fn realloc(&self,p:*mut u8,l:std::alloc::Layout,n:usize)->*mut u8{ALLOCS.fetch_add(1,Ordering::Relaxed);unsafe{std::alloc::System.realloc(p,l,n)}}}
#[global_allocator]static ALLOCATOR:CountAllocator=CountAllocator;
fn ctx(x:f64)->ToolContext{ToolContext::new(V::X*x,Ray::new(V::new(1.,1.,10.),-V::Z))}
fn main(){let mut s=Scene::new();for i in 0..50_000{s.image_planes.push(ImagePlane::new("reference",V::X*i as f64,V::X,V::Y));}let id=s.image_planes[0].id;s.select(SelectionItem::ImagePlane(0));let mut t=MoveTool::new();t.on_click(&mut s,&ctx(0.));t.on_move(&mut s,&ctx(1.));let scanned=t.image_membership_scanned;let rebuilt=t.image_membership_rebuilds;let epoch=s.image_planes.membership_epoch();let allocated=ALLOCS.load(Ordering::Relaxed);let start=std::time::Instant::now();for i in 2..1002{t.on_move(&mut s,&ctx(i as f64));}let warm_us=start.elapsed().as_micros();let warm_allocs=ALLOCS.load(Ordering::Relaxed)-allocated;assert_eq!(t.image_membership_scanned,scanned);assert_eq!(t.image_membership_rebuilds,rebuilt);assert_eq!(s.image_planes.membership_epoch(),epoch);assert_eq!(warm_allocs,0);
 s.image_planes.reverse();t.on_move(&mut s,&ctx(1002.));assert_eq!(s.image_planes[49_999].id,id);assert_eq!(t.image_membership_rebuilds,rebuilt+1);let moved=s.image_planes.remove(49_999);t.on_move(&mut s,&ctx(1003.));let scanned_detached=t.image_membership_scanned;let alloc_before=ALLOCS.load(Ordering::Relaxed);for i in 1004..2004{t.on_move(&mut s,&ctx(i as f64));}let detached_allocs=ALLOCS.load(Ordering::Relaxed)-alloc_before;assert_eq!(t.image_membership_scanned,scanned_detached);assert_eq!(detached_allocs,0);s.image_planes.insert(0,moved);t.on_move(&mut s,&ctx(2004.));assert_eq!(s.image_planes[0].id,id);let rebuilt_before=t.image_membership_rebuilds;s.image_planes=s.image_planes.clone();t.on_move(&mut s,&ctx(2005.));assert_eq!(t.image_membership_rebuilds,rebuilt_before+1);let old_epoch=s.image_planes.membership_epoch();{let mut pose=s.image_planes.pose_mut(0).unwrap();pose.set_origin(V::X*999.);std::mem::forget(pose);}assert_eq!(s.image_planes.membership_epoch(),old_epoch);assert_eq!(s.image_planes[0].origin,V::X*999.);assert_eq!(s.image_planes[0].id,id);let old_epoch=s.image_planes.membership_epoch();{s.image_planes.poses_mut().reverse();}assert_ne!(s.image_planes.membership_epoch(),old_epoch);let old_epoch=s.image_planes.membership_epoch();for pose in s.image_planes.iter_mut(){pose.opacity=0.5;}assert_ne!(s.image_planes.membership_epoch(),old_epoch);println!("{}",serde_json::json!({"planes":50_000,"warm_hovers":1000,"warm_scans":0,"warm_allocations":warm_allocs,"warm_us":warm_us,"detached_hovers":1000,"detached_scans":0,"detached_allocations":detached_allocs,"structural_invalidations":4,"restricted_forgotten_pose":true,"identity_capable_borrow_guards":2,"exact":true}));}
